<?php require __DIR__ . "/vendor/autoload.php"; $app = require_once __DIR__ . "/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $inv = App\Models\Invitation::where("email", "investorviewer@test.com")->first(); if($inv) { echo "Found invite for ".$inv->email."\n"; $inv->status = "accepted"; $inv->save(); $user = App\Models\User::firstOrCreate(["email" => "investorviewer@test.com"], ["name" => "Investor Viewer", "password" => bcrypt("password")]); $user->roles()->syncWithoutDetaching([$inv->role_id => ["company_id" => $inv->company_id]]); echo "User created and role assigned.\n"; } else { echo "Invite not found.\n"; }
